const body = $input.first()?.json?.body || $input.first()?.json || {};
const message = String(body.message || body.prompt || body.topic || '').trim();
if (!message) throw new Error('Missing message/topic.');
const pages = Math.max(4, Math.min(20, Number(body.pages) || 12));
return [{ json: {
  userId: String(body.userId || 'anonymous'),
  message,
  topic: String(body.topic || message),
  targetAge: body.targetAge || body.age || 5,
  pages,
  language: String(body.language || 'zh-CN'),
  tone: String(body.tone || '温柔、安心、亲子共读'),
  visualStyle: String(body.visualStyle || body.style || '温柔水彩绘本，暖色，圆润角色，低对比度'),
  outputType: String(body.outputType || 'book'),
  category: String(body.category || '')
} }];

const request = $('Normalize Request').first().json;
const rag = $input.first().json || {};
const system = '你是专业儿童绘本编辑、儿童心理友好写作者和图像分镜导演。只输出严格 JSON，不要 Markdown。';
const user = `请根据用户需求和参考资料生成一本儿童绘本的完整结构。

用户需求:
${JSON.stringify(request, null, 2)}

参考资料:
${rag.context || '无'}

要求:
1. 适合目标年龄，语言短、清楚、温柔。
2. 先给 storyPlan，再给 pages。
3. pages 数量必须等于 ${request.pages}。
4. 每页包含 page, text, scene, emotion, educationalGoal, imagePrompt, negativePrompt。
5. imagePrompt 用英文，保持角色一致性，适合图像模型。
6. negativePrompt 避免恐怖、暴力、文字乱码、畸形肢体、品牌角色侵权。
7. 不生成视频。

输出 JSON 形状:
{"title":"string","storyPlan":{"theme":"string","mainCharacter":{"name":"string","visualIdentity":"string","traits":["string"]},"storyArc":["string"],"visualStyleGuide":"string"},"pages":[{"page":1,"text":"string","scene":"string","emotion":"string","educationalGoal":"string","imagePrompt":"English image prompt","negativePrompt":"English negative prompt"}]}`;
return [{ json: { request, rag, messages: [ { role: 'system', content: system }, { role: 'user', content: user } ] } }];

const request = $('Build LLM Prompt').first().json.request;
const rag = $('Build LLM Prompt').first().json.rag;
const response = $input.first().json || {};
let content = response.choices?.[0]?.message?.content || response.output_text || response.text || '';
if (typeof content !== 'string') content = JSON.stringify(content);
content = content.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
let book;
try {
  book = JSON.parse(content);
} catch (error) {
  const match = content.match(/\{[\s\S]*\}/);
  if (!match) throw new Error('The model did not return parseable JSON.');
  book = JSON.parse(match[0]);
}
if (!Array.isArray(book.pages)) book.pages = [];
book.pages = book.pages.slice(0, request.pages).map((page, index) => ({
  page: Number(page.page) || index + 1,
  text: String(page.text || '').trim(),
  scene: String(page.scene || '').trim(),
  emotion: String(page.emotion || '').trim(),
  educationalGoal: String(page.educationalGoal || '').trim(),
  imagePrompt: String(page.imagePrompt || '').trim(),
  negativePrompt: String(page.negativePrompt || 'scary, horror, violence, distorted hands, extra limbs, unreadable text, watermark, logo').trim()
}));
if (book.pages.length !== request.pages) {
  book.warning = `Expected ${request.pages} pages but got ${book.pages.length}.`;
}
return [{ json: {
  success: true,
  outputType: 'book',
  request,
  rag: {
    referenceCount: rag.referenceCount || 0,
    references: rag.references || []
  },
  book
} }];
